/**
 * Content pipeline: turns the human-editable sources in /content into ready-to-render
 * files in /src/generated. Runs automatically before `npm run dev` and `npm run build`.
 *
 *  content/catalog.json              courses and lesson order (titles, leads, outcomes)
 *  content/lessons/<course>/<id>.html lesson bodies (HTML + LaTeX + code + <!--FIG:x--> + [[lesson-id]] links)
 *  content/quizzes/<course>.quiz     graded questions (see README for the format)
 *  content/exercises/<course>.ex     Python code exercises with tests
 *  content/figures/<name>.svg        diagrams (generated by tools/figures/make_figs.py)
 *  content/pages/*.html              standalone pages (start, cheat sheet, resources)
 *  content/glossary.json, content/projects.json
 *
 * Math is pre-rendered with KaTeX and code is pre-highlighted with highlight.js, so the browser
 * only needs the KaTeX stylesheet. Any LaTeX error, broken link or malformed question fails the build.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import katex from 'katex';
import hljs from 'highlight.js/lib/core';
import python from 'highlight.js/lib/languages/python';
import bash from 'highlight.js/lib/languages/bash';
import sql from 'highlight.js/lib/languages/sql';
import dockerfile from 'highlight.js/lib/languages/dockerfile';
import plaintext from 'highlight.js/lib/languages/plaintext';
import javascript from 'highlight.js/lib/languages/javascript';
import json from 'highlight.js/lib/languages/json';
import markdown from 'highlight.js/lib/languages/markdown';
import yaml from 'highlight.js/lib/languages/yaml';

hljs.registerLanguage('python', python);
hljs.registerLanguage('bash', bash);
hljs.registerLanguage('sql', sql);
hljs.registerLanguage('dockerfile', dockerfile);
hljs.registerLanguage('plaintext', plaintext);
hljs.registerLanguage('javascript', javascript);
hljs.registerLanguage('json', json);
hljs.registerLanguage('markdown', markdown);
hljs.registerLanguage('yaml', yaml);

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const CONTENT = path.join(ROOT, 'content');
const OUT = path.join(ROOT, 'src', 'generated');
const errors = [];
const warnings = [];
const LENIENT = process.argv.includes('--lenient');
const fail = (where, msg) => errors.push(`${where}: ${msg}`);
/** Problems that block a release but not local drafting (`npm run content -- --lenient`). */
const soft = (where, msg) => (LENIENT ? warnings : errors).push(`${where}: ${msg}`);
const readJson = (p, fallback) => (fs.existsSync(p) ? JSON.parse(read(p)) : fallback);
const read = (p) => fs.readFileSync(p, 'utf8');
const write = (p, s) => {
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, s);
};

/* ---------------------------------------------------------------- catalog */
const catalog = JSON.parse(read(path.join(CONTENT, 'catalog.json')));
const lessonIndex = new Map(); // id -> { course, lesson, n }
const courseIndex = new Map();
for (const c of catalog.courses) {
  courseIndex.set(c.id, c);
  c.lessons.forEach((l, i) => {
    if (lessonIndex.has(l.id)) fail('catalog', `duplicate lesson id ${l.id}`);
    lessonIndex.set(l.id, { course: c, lesson: l, n: i + 1 });
  });
}

/* ---------------------------------------------------------------- figures */
const figures = new Map();
for (const f of fs.readdirSync(path.join(CONTENT, 'figures'))) {
  if (f.endsWith('.svg')) figures.set(f.slice(0, -4), read(path.join(CONTENT, 'figures', f)));
}
const usedFigures = new Set();

/* ---------------------------------------------------------------- helpers */
const decode = (s) =>
  s.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
const escapeHtml = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let mathCount = 0;

function tex(src, display, where) {
  mathCount++;
  try {
    return katex.renderToString(decode(src).trim(), { displayMode: display, throwOnError: true, strict: 'ignore', output: 'htmlAndMathml' });
  } catch (e) {
    fail(where, `LaTeX error: ${e.message.split('\n')[0]} in "${src.slice(0, 80)}"`);
    return escapeHtml(src);
  }
}

/** Render $$...$$ and \( ... \) everywhere except inside <pre> blocks. */
function renderMath(html, where) {
  return html
    .split(/(<pre[\s\S]*?<\/pre>)/)
    .map((seg) =>
      seg.startsWith('<pre')
        ? seg
        : seg
            .replace(/\$\$([\s\S]+?)\$\$/g, (_, t) => tex(t, true, where))
            .replace(/\\\(([\s\S]+?)\\\)/g, (_, t) => tex(t, false, where)),
    )
    .join('');
}

function highlight(html, where) {
  return html.replace(/<pre><code class="language-([\w-]+)">([\s\S]*?)<\/code><\/pre>/g, (_, lang, code) => {
    const language = hljs.getLanguage(lang) ? lang : 'plaintext';
    if (!hljs.getLanguage(lang)) fail(where, `unknown code language "${lang}"`);
    const out = hljs.highlight(decode(code), { language, ignoreIllegals: true }).value;
    return `<pre class="code" data-lang="${lang}"><code class="hljs language-${lang}">${out}</code></pre>`;
  });
}

function expandFigures(html, where) {
  return html.replace(/<!--FIG:([a-z0-9_]+)-->/g, (_, name) => {
    const svg = figures.get(name);
    if (!svg) {
      fail(where, `missing figure ${name}`);
      return '';
    }
    usedFigures.add(name);
    const label = (svg.match(/aria-label="([^"]*)"/) || [, ''])[1];
    return `<figure class="fig">${svg}<figcaption>${label}</figcaption></figure>`;
  });
}

function links(html, where) {
  return html.replace(/\[\[(course:)?([a-z0-9-]+)\]\]/g, (_, isCourse, id) => {
    if (isCourse) {
      const c = courseIndex.get(id);
      if (!c) return fail(where, `unknown course link ${id}`), id;
      return `<a class="xref" href="#/course/${id}">${escapeHtml(c.title)}</a>`;
    }
    const hit = lessonIndex.get(id);
    if (!hit) return fail(where, `unknown lesson link ${id}`), id;
    return `<a class="xref" href="#/course/${hit.course.id}/${id}">${escapeHtml(hit.lesson.title)}</a>`;
  });
}

const slug = (s) =>
  s.toLowerCase().replace(/<[^>]+>/g, '').replace(/&[a-z]+;/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 60);

function headings(html) {
  const toc = [];
  const used = new Set();
  html = html.replace(/<h3>([\s\S]*?)<\/h3>/g, (_, inner) => {
    let id = slug(inner) || 'section';
    while (used.has(id)) id += '-x';
    used.add(id);
    const text = decode(inner.replace(/<[^>]+>/g, '')).trim();
    toc.push({ id, text });
    return `<h3 id="${id}">${inner}</h3>`;
  });
  return { html, toc };
}

const plain = (html) =>
  decode(
    html
      .replace(/<svg[\s\S]*?<\/svg>/g, ' ')
      .replace(/<pre[\s\S]*?<\/pre>/g, ' ')
      .replace(/<[^>]+>/g, ' '),
  )
    .replace(/\\\(|\\\)|\$\$/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

/** Inline formatting for short authored strings (quiz text, glossary, projects). */
function inline(s, where) {
  let h = escapeHtml(s.trim());
  h = h.replace(/`([^`]+)`/g, '<code>$1</code>');
  h = h.replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>');
  h = links(h, where);
  return renderMath(h, where);
}

/** Paragraph-aware formatting for longer authored text (exercise prompts). */
function block(s, where) {
  return s
    .trim()
    .split(/\n\s*\n/)
    .map((p) => {
      const lines = p.split('\n');
      if (lines.every((l) => /^\s*- /.test(l))) return `<ul>${lines.map((l) => `<li>${inline(l.replace(/^\s*- /, ''), where)}</li>`).join('')}</ul>`;
      return `<p>${inline(p.replace(/\n/g, ' '), where)}</p>`;
    })
    .join('');
}

function processHtml(html, where) {
  html = expandFigures(html, where);
  html = links(html, where);
  html = highlight(html, where);
  html = renderMath(html, where);
  return headings(html);
}

/* ---------------------------------------------------------------- quizzes */
function parseQuiz(text, file) {
  const byLesson = {};
  let lesson = null;
  let q = null;
  const flush = () => {
    if (!q) return;
    const where = `${file} [${lesson}] "${q.text.slice(0, 50)}"`;
    const out = { prompt: inline(q.text, where), explanation: q.expl.length ? inline(q.expl.join(' '), where) : '' };
    const correct = q.options.filter((o) => o.ok).length;
    if (q.options.length) {
      if (q.answer !== null) fail(where, 'has both options and an = answer');
      if (correct === 0) fail(where, 'no correct option (*)');
      out.type = correct > 1 ? 'multi' : 'single';
      out.options = q.options.map((o) => inline(o.text, where));
      out.answer = correct > 1 ? q.options.flatMap((o, i) => (o.ok ? [i] : [])) : q.options.findIndex((o) => o.ok);
    } else if (q.answer === null) {
      fail(where, 'no options and no = answer');
    } else if (/^(true|false)$/i.test(q.answer)) {
      out.type = 'tf';
      out.answer = q.answer.toLowerCase() === 'true';
    } else if (/^-?[\d.]+(e-?\d+)?\s*(±\s*[\d.]+(e-?\d+)?)?$/i.test(q.answer)) {
      const [a, tol] = q.answer.split('±').map((x) => x.trim());
      out.type = 'num';
      out.answer = Number(a);
      out.tol = tol !== undefined ? Number(tol) : Number.isInteger(Number(a)) && !a.includes('.') ? 0 : Math.abs(Number(a)) * 0.01;
      if (!Number.isFinite(out.answer) || !Number.isFinite(out.tol)) fail(where, `bad numeric answer ${q.answer}`);
    } else {
      out.type = 'text';
      out.answer = q.answer.split('|').map((x) => x.trim()).filter(Boolean);
      out.display = out.answer[0];
    }
    (byLesson[lesson] ||= []).push(out);
    q = null;
  };
  for (const raw of text.split('\n')) {
    const line = raw.trimEnd();
    if (line.startsWith('#')) continue;
    let m;
    if ((m = line.match(/^@lesson\s+([a-z0-9-]+)/))) {
      flush();
      lesson = m[1];
      if (lesson !== 'exam' && !lessonIndex.has(lesson)) fail(file, `unknown lesson ${lesson}`);
      continue;
    }
    if ((m = line.match(/^Q:\s*(.*)$/))) {
      flush();
      if (!lesson) fail(file, 'question before @lesson');
      q = { text: m[1], options: [], answer: null, expl: [], stage: 'q' };
      continue;
    }
    if (!q) {
      if (line.trim()) fail(file, `stray line: ${line.slice(0, 60)}`);
      continue;
    }
    if ((m = line.match(/^([-*]) (.*)$/))) {
      q.options.push({ ok: m[1] === '*', text: m[2] });
      q.stage = 'o';
    } else if ((m = line.match(/^= (.*)$/))) {
      q.answer = m[1].trim();
      q.stage = 'a';
    } else if ((m = line.match(/^> ?(.*)$/))) {
      q.expl.push(m[1]);
      q.stage = 'e';
    } else if (line.trim()) {
      if (q.stage === 'q') q.text += ' ' + line.trim();
      else if (q.stage === 'e') q.expl.push(line.trim());
      else if (q.stage === 'o') q.options[q.options.length - 1].text += ' ' + line.trim();
      else fail(file, `unexpected line: ${line.slice(0, 60)}`);
    }
  }
  flush();
  return byLesson;
}

/* ---------------------------------------------------------------- exercises */
function parseExercises(text, file) {
  const out = [];
  for (const chunk of text.split(/^@exercise\s+/m).slice(1)) {
    const id = chunk.split('\n')[0].trim();
    const where = `${file} [${id}]`;
    const [head, ...rest] = chunk.split(/^--- (\w+)\s*$/m);
    const meta = {};
    for (const l of head.split('\n').slice(1)) {
      const m = l.match(/^(\w+):\s*(.*)$/);
      if (m) meta[m[1]] = m[2].trim();
    }
    const parts = {};
    for (let i = 0; i < rest.length; i += 2) parts[rest[i]] = rest[i + 1].replace(/^\n/, '').replace(/\s+$/, '') + '\n';
    for (const k of ['prompt', 'starter', 'solution', 'tests']) if (!parts[k]) fail(where, `missing --- ${k}`);
    if (!lessonIndex.has(meta.lesson)) fail(where, `unknown lesson ${meta.lesson}`);
    out.push({
      id,
      lesson: meta.lesson,
      title: meta.title || id,
      packages: meta.packages ? meta.packages.split(',').map((s) => s.trim()) : [],
      prompt: block(parts.prompt || '', where),
      starter: parts.starter,
      solution: parts.solution,
      tests: parts.tests,
    });
  }
  return out;
}

/* ---------------------------------------------------------------- build */
fs.rmSync(OUT, { recursive: true, force: true });
const search = [];
let lessonCount = 0;
const quizzesByCourse = {};
const examBank = {};

for (const c of catalog.courses) {
  const qfile = path.join(CONTENT, 'quizzes', `${c.id}.quiz`);
  const qs = fs.existsSync(qfile) ? parseQuiz(read(qfile), `${c.id}.quiz`) : {};
  const efile = path.join(CONTENT, 'exercises', `${c.id}.ex`);
  const ex = fs.existsSync(efile) ? parseExercises(read(efile), `${c.id}.ex`) : [];
  quizzesByCourse[c.id] = {};
  let courseMinutes = 0;
  let courseQuestions = 0;

  for (const l of c.lessons) {
    const where = `lesson ${l.id}`;
    const file = path.join(CONTENT, 'lessons', c.id, `${l.id}.html`);
    if (!fs.existsSync(file)) {
      soft(where, `missing file content/lessons/${c.id}/${l.id}.html`);
      continue;
    }
    const src = read(file);
    const { html, toc } = processHtml(src, where);
    write(path.join(OUT, 'lessons', `${l.id}.html`), html);
    const text = plain(html);
    const words = text.split(' ').length;
    const figs = (html.match(/<figure class="fig">/g) || []).length;
    const widgets = [...src.matchAll(/data-widget="(\w+)"/g)].map((m) => m[1]);
    const displayEq = (src.match(/\$\$/g) || []).length / 2;
    const questions = (qs[l.id] || []).map((q, i) => ({ id: `${l.id}-${i + 1}`, ...q }));
    if (questions.length < 3) soft(where, `only ${questions.length} quiz questions (need at least 3)`);
    quizzesByCourse[c.id][l.id] = questions;
    const lessonEx = ex.filter((e) => e.lesson === l.id);
    Object.assign(l, {
      // Study time, not skim time: dense technical prose, equations, figures and demos all slow reading down.
      minutes: Math.max(6, Math.round(words / 120 + figs * 0.7 + widgets.length * 4 + displayEq * 0.4)),
      toc,
      questions: questions.length,
      exercises: lessonEx.map((e) => e.id),
      figures: figs,
      widgets,
    });
    courseMinutes += l.minutes + questions.length;
    courseQuestions += questions.length;
    lessonCount++;
    search.push({ t: 'lesson', id: l.id, course: c.id, title: l.title, lead: l.lead, head: toc.map((h) => h.text).join(' · '), text: text.slice(0, 2500) });
  }
  const exam = (qs.exam || []).map((q, i) => ({ id: `${c.id}-exam-${i + 1}`, ...q }));
  if (exam.length < 3) soft(`course ${c.id}`, `only ${exam.length} exam-only questions (need at least 3)`);
  examBank[c.id] = exam;
  quizzesByCourse[c.id].__exam = exam;
  for (const k of Object.keys(qs)) if (k !== 'exam' && !c.lessons.some((l) => l.id === k)) fail(`${c.id}.quiz`, `questions for ${k} which is not in this course`);
  write(path.join(OUT, 'quizzes', `${c.id}.json`), JSON.stringify(quizzesByCourse[c.id]));
  write(path.join(OUT, 'exercises', `${c.id}.json`), JSON.stringify(ex));
  Object.assign(c, { minutes: courseMinutes, questions: courseQuestions, examQuestions: exam.length, exercises: ex.length });
}

/* pages */
const pages = {};
for (const f of fs.readdirSync(path.join(CONTENT, 'pages'))) {
  const name = f.replace(/\.html$/, '');
  const { html, toc } = processHtml(read(path.join(CONTENT, 'pages', f)), `page ${name}`);
  write(path.join(OUT, 'pages', `${name}.html`), html);
  pages[name] = { toc };
}

/* glossary */
const glossary = readJson(path.join(CONTENT, 'glossary.json'), []).map((g) => {
  const where = `glossary "${g.term}"`;
  if (g.lesson && !lessonIndex.has(g.lesson)) fail(where, `unknown lesson ${g.lesson}`);
  const hit = g.lesson && lessonIndex.get(g.lesson);
  search.push({ t: 'term', id: g.term, title: g.term, lead: plain(inline(g.def, where)), course: hit ? hit.course.id : '' });
  return { term: g.term, def: inline(g.def, where), lesson: g.lesson || null, course: hit ? hit.course.id : null };
});
glossary.sort((a, b) => a.term.localeCompare(b.term, 'en', { sensitivity: 'base' }));
write(path.join(OUT, 'glossary.json'), JSON.stringify(glossary));

/* projects */
const projects = readJson(path.join(CONTENT, 'projects.json'), []).map((p) => {
  const where = `project ${p.id}`;
  for (const c of p.courses || []) if (!courseIndex.has(c)) fail(where, `unknown course ${c}`);
  return {
    ...p,
    summary: inline(p.summary, where),
    brief: block(p.brief, where),
    milestones: p.milestones.map((m) => ({ id: m.id, text: inline(m.text, where), detail: m.detail ? inline(m.detail, where) : '' })),
    stretch: (p.stretch || []).map((s) => inline(s, where)),
    rubric: (p.rubric || []).map((s) => inline(s, where)),
  };
});
write(path.join(OUT, 'projects.json'), JSON.stringify(projects));
for (const p of projects) search.push({ t: 'project', id: p.id, title: p.title, lead: plain(p.summary), course: '' });

for (const name of figures.keys()) if (!usedFigures.has(name)) soft('figures', `figure ${name} is never used`);

catalog.generatedAt = new Date().toISOString();
write(path.join(OUT, 'catalog.json'), JSON.stringify(catalog));
write(path.join(OUT, 'pages.json'), JSON.stringify(pages));
write(path.join(OUT, 'search.json'), JSON.stringify(search));

if (warnings.length) console.warn(`! ${warnings.length} warning(s) (lenient mode):\n  - ` + warnings.slice(0, 15).join('\n  - ') + (warnings.length > 15 ? '\n  - …' : ''));
if (errors.length) {
  console.error(`\n✗ Content build failed with ${errors.length} problem(s):\n  - ` + errors.join('\n  - ') + '\n');
  process.exit(1);
}
const totalQ = catalog.courses.reduce((s, c) => s + c.questions + c.examQuestions, 0);
const totalEx = catalog.courses.reduce((s, c) => s + c.exercises, 0);
console.log(
  `✓ content: ${catalog.courses.length} courses, ${lessonCount} lessons, ${totalQ} questions, ${totalEx} code exercises, ` +
    `${usedFigures.size} figures, ${mathCount} equations, ${glossary.length} glossary terms, ${projects.length} projects`,
);
